.tab-chase-border-lime:before {
  content: "";
  z-index: 0;
  background: conic-gradient(#0000 20%, #cf0 35%, #fdffcc 40%, #cf0 45%, #0000 60%);
  width: 300%;
  height: 300%;
  animation: 4s linear infinite tab-chase-spin;
  position: absolute;
  top: -100%;
  left: -100%;
}

.tab-chase-border-lime > div {
  z-index: 1;
  position: relative;
}

